testWidgets('list update keeps row states', (tester) async {
  await tester.pumpWidget(harness(info(scrips20)));
  final before = tester.stateList(find.byType(WatchlistItem)).map(identityHashCode).toList();
  await tester.pumpWidget(harness(info(scrips20)));
  final after = tester.stateList(find.byType(WatchlistItem)).map(identityHashCode).toList();
  expect(after, before);
}, experimentalLeakTesting: LeakTesting.settings.withTrackedAll());

testWidgets('rows cancel tooltip subscriptions', (tester) async {
  for (var i = 0; i < 10; i++) {
    await tester.pumpWidget(harness(info(scrips20)));
    await tester.pumpWidget(const SizedBox());
  }
  expect(cubit.toolTipSteamSubscription.hasListener, isFalse);
}, experimentalLeakTesting: LeakTesting.settings.withTrackedAll());

test('togglePersistHeader emits only on change', () async {
  final states = <WatchlistState>[];
  final sub = cubit.stream.listen(states.add);
  cubit.togglePersistHeader(true);
  for (var i = 0; i < 50; i++) { cubit.togglePersistHeader(false); }
  await Future<void>.delayed(Duration.zero);
  expect(states.whereType<TogglePersistHeader>().length, 2);
  await sub.cancel();
});
